def find_peak_util(arr, n):
    for i in range(n):
        left = arr[i-1] if i > 0 else -1
        right = arr[i+1] if i < n-1 else -1
        if arr[i] > left and arr[i] > right:
            return i
    return -1

def otherside_rightangle(a, b):
    if a > b:
        return (a**2 - b**2)**0.5
    else:
        return (b**2 - a**2)**0.5

import re

def split_list(s):
    return re.findall('[A-Z][^A-Z]*', s)

def find_peak_util(arr, n):
    for i in range(n):
        if (i == 0 or arr[i] > arr[i-1]) and (i == n-1 or arr[i] > arr[i+1]):
            return i
    return -1

def otherside_rightangle(a, b):
    if a > b:
        hypotenuse = a
        other = b
    else:
        hypotenuse = b
        other = a
    return (hypotenuse**2 - other**2)**0.5 if hypotenuse**2 > other**2 else (a**2 + b**2)**0.5

import math

def otherside_rightangle(a, b):
    return math.sqrt(a**2 + b**2)

import re

def split_list(s):
    return re.split(r'(?<=[a-z])(?=[A-Z])', s)

